public class Main {
    public static void main(String[] args) {
        Hewan[] daftar = { new Kucing(), new Hewan() };

        for (Hewan h : daftar) {
            h.suara();
            if (h instanceof Kucing) {
                Kucing k = (Kucing) h;
                k.mengeong();
            }
        }
    }
}

class Hewan {
    void suara() {
        System.out.println("Hewan bersuara");
    }
}

class Kucing extends Hewan {
    @Override
    void suara() {
        System.out.println("Meong!");
    }

    void mengeong() {
        System.out.println("Kucing manja");
    }
}

