public class Main {
    public static void main(String[] args) {
        Produk[] isi = {new Minuman("Es Teh", 400), new Produk("Sabun")};
        for (Produk p : isi) {
            if (p instanceof Minuman) {
                Minuman m = (Minuman) p;
                System.out.println(m.nama + " " + m.ml + " ml");
            } else {
                System.out.println(p.nama);
            }
        }
    }
}

class Produk {
    String nama;

    Produk(String nama) {
        this.nama = nama;
    }
}

class Minuman extends Produk {
    int ml;

    Minuman(String nama, int ml) {
        super(nama);
        this.ml = ml;
    }
}

public class Main {
    public static void main(String[] args) {
        Produk[] isi = {new Minuman("Es Teh", 400), new Produk("Sabun"), new Makanan("Roti", 250)};
        for (Produk p : isi) {
            if (p instanceof Minuman) {
                Minuman m = (Minuman) p;
                System.out.println(m.nama + " " + m.ml + " ml");
            } else if (p instanceof Makanan) {
                Makanan mk = (Makanan) p;
                System.out.println(mk.nama + " " + mk.kalori + " kkal");
            } else {
                System.out.println(p.nama);
            }
        }
    }
}

