    String nama;

    Produk(String nama) {
        this.nama = nama;
    }
}

class Minuman extends Produk {
    int ml;

    Minuman(String nama, int ml) {
        super(nama);
        this.ml = ml;
    }
}

class Makanan extends Produk {
    int kalori;

    Makanan(String nama, int kalori) {
        super(nama);
        this.kalori = kalori;
    }
}

